$query=function($sql,$reason)use($db){$res=$db->query($sql);if(!$res){fwrite(STDERR,'M083_SCHEMA=FAIL REASON='.$reason."\n");exit(1);}return$res;};
$exists=function($name)use($query,$db){$table=MAIN_DB_PREFIX.$name;$pattern=str_replace(array('\\','_','%'),array('\\\\','\\_','\\%'),$table);return$db->num_rows($query("SHOW TABLES LIKE '".$db->escape($pattern)."'",'TABLE_CHECK_FAILED'))===1;};
$normalizeType=function($type){$type=strtolower(trim((string)$type));$type=preg_replace('/^(tinyint|smallint|mediumint|int|integer|bigint)\(\d+\)$/','$1',$type);return $type==='integer'?'int':$type;};
$normalizeDefault=function($value){if($value===null)return null;$value=strtolower(trim((string)$value,"'\" "));$value=preg_replace('/^current_timestamp\(\)$/','current_timestamp',$value);if(preg_match('/^-?\d+\.\d+$/',$value)){$value=rtrim(rtrim($value,'0'),'.');if($value==='-0')$value='0';}return$value;};
$parseDefinition=function($relative)use($normalizeType,$normalizeDefault){
 $path=dirname(__DIR__,2).'/'.$relative;$sql=file_get_contents($path);if($sql===false||trim($sql)==='')return false;$columns=array();$indexes=array();
 foreach(preg_split('/\R/',$sql)as$line){$line=trim($line," \t\r\n,");if($line===''||stripos($line,'CREATE TABLE')===0||$line[0]===')')continue;
  if(preg_match('/^UNIQUE KEY\s+([A-Za-z0-9_]+)\s*\(([^)]+)\)$/i',$line,$m)||preg_match('/^KEY\s+([A-Za-z0-9_]+)\s*\(([^)]+)\)$/i',$line,$m)){$unique=stripos($line,'UNIQUE KEY')===0?0:1;$indexes[$m[1]]=array('non_unique'=>$unique,'columns'=>array_map(function($v){return trim($v," `\t");},explode(',',$m[2])));continue;}
  if(!preg_match('/^([A-Za-z0-9_]+)\s+([A-Za-z]+(?:\(\d+(?:,\d+)?\))?)\s*(.*)$/i',$line,$m))return false;$tail=$m[3];$type=$normalizeType($m[2]);$primary=preg_match('/\bPRIMARY\s+KEY\b/i',$tail)===1;$explicitNull=preg_match('/(?:^|\s)NULL(?:\s|$)/i',$tail)===1;$notNull=$primary||preg_match('/\bNOT\s+NULL\b/i',$tail)===1||($type==='timestamp'&&!$explicitNull);$default=null;if(preg_match('/\bDEFAULT\s+((?:\'[^\']*\')|(?:\"[^\"]*\")|[^\s]+)/i',$tail,$d))$default=$normalizeDefault($d[1]);$extra=array();if(preg_match('/\bAUTO_INCREMENT\b/i',$tail))$extra[]='auto_increment';if(preg_match('/\bON\s+UPDATE\s+CURRENT_TIMESTAMP(?:\(\))?/i',$tail))$extra[]='on update current_timestamp';$columns[$m[1]]=array('type'=>$type,'null'=>$notNull?'NO':'YES','default'=>$default,'extra'=>implode(' ',$extra));if($primary)$indexes['PRIMARY']=array('non_unique'=>0,'columns'=>array($m[1]));
 }
 return array('sql'=>$sql,'columns'=>$columns,'indexes'=>$indexes);
};
$ready=function($name,$relative)use($exists,$query,$db,$parseDefinition,$normalizeType,$normalizeDefault){
 if(!$exists($name))return false;$expected=$parseDefinition($relative);if($expected===false)return false;$table=MAIN_DB_PREFIX.$name;$actual=array();$res=$query("SHOW COLUMNS FROM `".$table."`",'COLUMN_CHECK_FAILED');while($row=$db->fetch_object($res)){$extra=strtolower(trim(preg_replace('/\s+/',' ',(string)$row->Extra)));$extra=str_replace('on update current_timestamp()','on update current_timestamp',$extra);$actual[(string)$row->Field]=array('type'=>$normalizeType($row->Type),'null'=>(string)$row->Null,'default'=>$normalizeDefault($row->Default),'extra'=>$extra);}if($actual!==$expected['columns'])return false;
 $indexes=array();$res=$query("SHOW INDEX FROM `".$table."`",'INDEX_CHECK_FAILED');while($row=$db->fetch_object($res)){$key=(string)$row->Key_name;if(!isset($indexes[$key]))$indexes[$key]=array('non_unique'=>(int)$row->Non_unique,'columns'=>array());$indexes[$key]['columns'][(int)$row->Seq_in_index]=(string)$row->Column_name;}foreach($indexes as&$index){ksort($index['columns']);$index['columns']=array_values($index['columns']);}unset($index);ksort($indexes);$expectedIndexes=$expected['indexes'];ksort($expectedIndexes);if($indexes!==$expectedIndexes)return false;
 $res=$query("SELECT ENGINE FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='".$db->escape($table)."'",'ENGINE_CHECK_FAILED');$row=$db->fetch_object($res);return $row&&strtoupper((string)$row->ENGINE)==='INNODB';
};
$prerequisites=function()use($query,$db){foreach(array('cpo_operation','cpo_activity','cpo_document','cpcc_financial_entry','chinaplanetlogistics','paiement','paiement_facture','facture','paiementfourn','paiementfourn_facturefourn','facture_fourn','bank','bank_url','bank_account','societe_remise_except')as$name){$table=MAIN_DB_PREFIX.$name;$pattern=str_replace(array('\\','_','%'),array('\\\\','\\_','\\%'),$table);if($db->num_rows($query("SHOW TABLES LIKE '".$db->escape($pattern)."'",'PREREQUISITE_CHECK_FAILED'))!==1)return false;}return true;};
$hasVisibility=function()use($query,$db){$res=$query("SHOW COLUMNS FROM `".MAIN_DB_PREFIX."chinaplanetlogistics` LIKE 'customer_visible'",'VISIBILITY_COLUMN_CHECK_FAILED');return $db->num_rows($res)===1;};
$guardState=function()use($query,$db){$present=0;$invalid=0;$reflection=new ReflectionClass('ManagedFundsNativeGuard');$method=$reflection->getMethod('definitions');$method->setAccessible(true);$definitions=$method->invoke(null);$normalize=function($sql){return strtoupper(trim(preg_replace('/\s+/',' ',str_replace('`','',(string)$sql))));};foreach($definitions as$name=>$definition){$res=$query("SELECT ACTION_TIMING,EVENT_MANIPULATION,EVENT_OBJECT_TABLE,ACTION_STATEMENT FROM INFORMATION_SCHEMA.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='".$db->escape($name)."'",'GUARD_COUNT_FAILED');$row=$db->fetch_object($res);if(!$row)continue;$present++;if(strtoupper((string)$row->ACTION_TIMING)!=='BEFORE'||strtoupper((string)$row->EVENT_MANIPULATION)!==$definition['event']||(string)$row->EVENT_OBJECT_TABLE!==$definition['table']||$normalize($row->ACTION_STATEMENT)!==$normalize($definition['body']))$invalid++;}return array($present,$invalid===0);};
$state=function()use($spec,$exists,$ready,$guardState){$present=0;$valid=0;$invalidNames=array();foreach($spec as$name=>$relative){if($exists($name)){$present++;if($ready($name,$relative))$valid++;else$invalidNames[]=$name;}}list($guards,$guardValid)=$guardState();return array($present,$valid,$guards,$guardValid,$invalidNames);};
$allEmpty=function($allowPartial)use($spec,$exists,$ready,$query,$db){foreach($spec as$name=>$relative){if(!$exists($name)){if(!$allowPartial)return false;continue;}if(!$ready($name,$relative))return false;$row=$db->fetch_object($query("SELECT COUNT(*) n FROM `".MAIN_DB_PREFIX.$name."`",'ROW_COUNT_FAILED'));if((int)$row->n!==0)return false;}return true;};

