}
if($present!==0||$guards!==0||!$guardValid){fwrite(STDERR,"M083_SCHEMA=FAIL REASON=NONEMPTY_PRESTATE\n");exit(1);}if(!$hasVisibility()){$query("ALTER TABLE `".MAIN_DB_PREFIX."chinaplanetlogistics` ADD COLUMN customer_visible tinyint NOT NULL DEFAULT 1 AFTER customer_note",'ALTER_LOGISTICS_CUSTOMER_VISIBLE_FAILED');}foreach($spec as$name=>$relative){$parsed=$parseDefinition($relative);if($parsed===false){fwrite(STDERR,"M083_SCHEMA=FAIL REASON=SQL_FILE_INVALID\n");exit(1);}$sql=preg_replace('/\bllx_/',MAIN_DB_PREFIX,$parsed['sql']);$query($sql,'CREATE_FAILED');if(!$ready($name,$relative)){fwrite(STDERR,"M083_SCHEMA=FAIL REASON=READINESS_FAILED TABLE=".$name."\n");exit(1);}}if(!ManagedFundsNativeGuard::install($db)||!ManagedFundsNativeGuard::verify($db)||!$hasVisibility()){fwrite(STDERR,"M083_SCHEMA=FAIL REASON=GUARD_INSTALL_FAILED\n");exit(1);}echo"M083_SCHEMA_APPLY=PASS TABLES=6 GUARDS=4 ROWS=0\n";
